fn handle_submit_with_inputs_contracts_and_header_mode(
    &mut self,
    run: RunId,
    workflow: CompiledWorkflow,
    inputs: &[(SlotIdx, SlotValue)],
    caps: CapabilitySet,
    action_contracts: &[vb_core::action::ActionContract],
    persist_header: bool,
